"use client";

import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";

import { mergeClassName } from "@/lib/utils";

function Tabs({
  className,
  orientation = "horizontal",
  ...props
}: TabsPrimitive.Root.Props) {
  return (
    <TabsPrimitive.Root
      data-slot="tabs"
      orientation={orientation}
      className={mergeClassName<TabsPrimitive.Root.State>(
        "flex w-full flex-col gap-3 data-[orientation=vertical]:flex-row",
        className,
      )}
      {...props}
    />
  );
}

function TabsList({ className, ...props }: TabsPrimitive.List.Props) {
  return (
    <TabsPrimitive.List
      data-slot="tabs-list"
      className={mergeClassName<TabsPrimitive.List.State>(
        "inline-flex h-11 max-w-full w-fit items-center justify-start overflow-x-auto gap-1 rounded-[var(--neu-radius-control)] border border-transparent bg-[var(--neu-surface)] [background-image:var(--neu-fill-inset)] p-1 shadow-[var(--neu-shadow-inset)] data-[orientation=vertical]:h-fit data-[orientation=vertical]:flex-col",
        className,
      )}
      {...props}
    />
  );
}

function TabsTrigger({
  className,
  ...props
}: TabsPrimitive.Tab.Props) {
  return (
    <TabsPrimitive.Tab
      data-slot="tabs-trigger"
      className={mergeClassName<TabsPrimitive.Tab.State>(
        "inline-flex h-8 shrink-0 flex-1 items-center justify-center gap-1.5 rounded-[calc(var(--neu-radius-control)-4px)] border border-transparent px-4 text-sm font-semibold whitespace-nowrap text-[var(--muted-foreground)] outline-hidden transition-[color,background-color,box-shadow,transform] duration-[var(--neu-duration)] motion-reduce:transition-none focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-[-2px] focus-visible:outline-[color:var(--ring)] hover:not-data-disabled:text-[var(--foreground)] data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50 data-[active]:border-[color:var(--neu-edge)] data-[active]:bg-[var(--neu-surface)] data-[active]:[background-image:var(--neu-fill-raised)] data-[active]:text-[var(--foreground)] data-[active]:shadow-[var(--neu-shadow-raised-sm)] [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        className,
      )}
      {...props}
    />
  );
}

function TabsContent({
  className,
  ...props
}: TabsPrimitive.Panel.Props) {
  return (
    <TabsPrimitive.Panel
      data-slot="tabs-content"
      className={mergeClassName<TabsPrimitive.Panel.State>(
        "flex-1 rounded-[var(--neu-radius-surface)] outline-hidden focus-visible:ring-2 focus-visible:ring-[var(--ring)]",
        className,
      )}
      {...props}
    />
  );
}

export { Tabs, TabsContent, TabsList, TabsTrigger };
